-- Seated versions of the standing dumbbell exercises, the incline hammer curl, the assisted dip
-- machine and the seated leg press. The dumbbell ones need a bench as well.
-- Further down, exercises whose names left out their equipment get it added. Their ids stay.
insert into public.exercises (id, name, instructions, equipment, muscles, rest_seconds, assisted, needs, strength_standard) values
  ('seated-dumbbell-curl', '{"en": "Seated Dumbbell Curl", "de": "Kurzhantel-Curls im Sitzen", "pt-PT": "Curl com halteres sentado", "pt-BR": "Rosca com halteres sentado", "ko": "시티드 덤벨 컬"}'::jsonb,
   '{"en": [{"title": "Start", "text": "Sit upright on the end of a bench with your feet flat and the dumbbells at your sides, elbows close to your body."}, {"title": "Curl", "text": "Bend your elbows and lift the weights towards your shoulders without leaning back."}, {"title": "Lower", "text": "Lower slowly until your arms are straight again."}], "de": [{"title": "Start", "text": "Setz dich aufrecht ans Ende einer Bank, die Füße flach am Boden. Die Kurzhanteln hängen seitlich, die Ellbogen bleiben nah am Körper."}, {"title": "Beugen", "text": "Beug die Ellbogen und heb die Gewichte Richtung Schultern, ohne dich nach hinten zu lehnen."}, {"title": "Absenken", "text": "Senk die Gewichte langsam ab, bis die Arme wieder gestreckt sind."}], "pt-PT": [{"title": "Início", "text": "Senta-te direito na ponta de um banco, com os pés bem assentes, os halteres ao lado do corpo e os cotovelos junto ao tronco."}, {"title": "Fletir", "text": "Flete os cotovelos e leva os pesos em direção aos ombros, sem inclinar o tronco para trás."}, {"title": "Descida", "text": "Desce devagar até os braços ficarem esticados outra vez."}], "pt-BR": [{"title": "Início", "text": "Sente com a coluna reta na ponta de um banco, pés apoiados no chão, halteres ao lado do corpo e cotovelos junto ao tronco."}, {"title": "Flexionar", "text": "Flexione os cotovelos e leve os pesos em direção aos ombros, sem inclinar o tronco para trás."}, {"title": "Descida", "text": "Desça devagar até os braços ficarem estendidos de novo."}], "ko": [{"title": "시작 자세", "text": "벤치 끝에 바르게 앉아 발을 바닥에 붙이고, 덤벨을 몸 옆에 늘어뜨린 채 팔꿈치를 몸에 붙여요."}, {"title": "들어 올리기", "text": "상체를 뒤로 젖히지 않고 팔꿈치를 굽혀 덤벨을 어깨 쪽으로 들어 올려요."}, {"title": "내리기", "text": "팔이 다시 펴질 때까지 천천히 내려요."}]}'::jsonb,
   'dumbbell', '{"biceps": 0.85, "forearms": 0.15}'::jsonb, 60, false, '[["dumbbell"], ["bench"]]'::jsonb, 0.27),
  ('seated-dumbbell-hammer-curl', '{"en": "Seated Dumbbell Hammer Curl", "de": "Hammercurls mit Kurzhanteln im Sitzen", "pt-PT": "Curl martelo com halteres sentado", "pt-BR": "Rosca martelo com halteres sentado", "ko": "시티드 덤벨 해머 컬"}'::jsonb,
   '{"en": [{"title": "Start", "text": "Sit upright on the end of a bench with your feet flat and the dumbbells at your sides, palms facing your body and elbows close to your torso."}, {"title": "Curl", "text": "Curl the dumbbells up with your thumbs on top until your forearms are nearly vertical. Don''t lean back."}, {"title": "Lower", "text": "Lower slowly, keeping the neutral grip, until your arms are straight again."}], "de": [{"title": "Start", "text": "Setz dich aufrecht ans Ende einer Bank, die Füße flach am Boden. Die Kurzhanteln hängen seitlich im Hammergriff, Handflächen zum Körper, Ellbogen nah am Oberkörper."}, {"title": "Beugen", "text": "Beug die Arme und heb die Hanteln mit den Daumen nach oben, bis die Unterarme fast senkrecht sind. Lehn dich nicht nach hinten."}, {"title": "Absenken", "text": "Senk die Hanteln im Hammergriff langsam ab, bis die Arme wieder gestreckt sind."}], "pt-PT": [{"title": "Início", "text": "Senta-te direito na ponta de um banco, com os pés bem assentes, os halteres ao lado do corpo, palmas viradas para dentro e cotovelos junto ao tronco."}, {"title": "Fletir", "text": "Flete os cotovelos e sobe os halteres com os polegares para cima, até os antebraços ficarem quase na vertical. Não inclines o tronco para trás."}, {"title": "Descida", "text": "Desce devagar, sem rodar os pulsos, até os braços ficarem esticados outra vez."}], "pt-BR": [{"title": "Início", "text": "Sente com a coluna reta na ponta de um banco, pés apoiados no chão, halteres ao lado do corpo, palmas voltadas para dentro e cotovelos junto ao tronco."}, {"title": "Flexionar", "text": "Flexione os cotovelos e suba os halteres com os polegares para cima, até os antebraços ficarem quase na vertical. Não incline o tronco para trás."}, {"title": "Descida", "text": "Desça devagar, sem girar os punhos, até os braços ficarem estendidos de novo."}], "ko": [{"title": "시작 자세", "text": "벤치 끝에 바르게 앉아 발을 바닥에 붙이고 덤벨을 몸 옆에 늘어뜨려요. 손바닥은 몸 쪽을 향하게 하고 팔꿈치는 몸통에 붙여요."}, {"title": "들어 올리기", "text": "엄지가 위를 향한 채 전완이 거의 수직이 될 때까지 덤벨을 들어 올려요. 상체를 뒤로 젖히지 마세요."}, {"title": "내리기", "text": "뉴트럴 그립을 유지하며 팔이 다시 펴질 때까지 천천히 내려요."}]}'::jsonb,
   'dumbbell', '{"biceps": 0.6, "forearms": 0.4}'::jsonb, 60, false, '[["dumbbell"], ["bench"]]'::jsonb, 0.27),
  ('seated-dumbbell-lateral-raise', '{"en": "Seated Dumbbell Lateral Raise", "de": "Seitheben mit Kurzhanteln im Sitzen", "pt-PT": "Elevação lateral com halteres sentado", "pt-BR": "Elevação lateral com halteres sentado", "ko": "시티드 덤벨 레터럴 레이즈"}'::jsonb,
   '{"en": [{"title": "Start", "text": "Sit upright on the end of a bench with your feet flat, the dumbbells at your sides and a slight bend in your elbows."}, {"title": "Raise", "text": "Lift the weights to shoulder height, leading with your elbows. Don''t lean or shrug."}, {"title": "Lower", "text": "Lower slowly over two to three seconds and keep the tension at the bottom."}], "de": [{"title": "Start", "text": "Setz dich aufrecht ans Ende einer Bank, die Füße flach am Boden. Die Kurzhanteln hängen seitlich, die Ellbogen sind leicht gebeugt."}, {"title": "Heben", "text": "Heb die Gewichte bis auf Schulterhöhe, die Ellbogen führen. Lehn dich nicht zurück und zieh die Schultern nicht hoch."}, {"title": "Absenken", "text": "Senk die Gewichte über zwei bis drei Sekunden ab und halte unten die Spannung."}], "pt-PT": [{"title": "Início", "text": "Senta-te direito na ponta de um banco, com os pés bem assentes, os halteres ao lado do corpo e os cotovelos ligeiramente fletidos."}, {"title": "Elevar", "text": "Eleva os pesos até à altura dos ombros, conduzindo com os cotovelos. Sem inclinar o tronco nem encolher os ombros."}, {"title": "Descida", "text": "Desce devagar, em dois a três segundos, e mantém a tensão em baixo."}], "pt-BR": [{"title": "Início", "text": "Sente com a coluna reta na ponta de um banco, pés apoiados no chão, halteres ao lado do corpo e cotovelos levemente flexionados."}, {"title": "Elevar", "text": "Eleve os pesos até a altura dos ombros, conduzindo com os cotovelos. Sem inclinar o tronco nem encolher os ombros."}, {"title": "Descida", "text": "Desça devagar, em dois a três segundos, e mantenha a tensão embaixo."}], "ko": [{"title": "시작 자세", "text": "벤치 끝에 바르게 앉아 발을 바닥에 붙이고, 덤벨을 몸 옆에 늘어뜨린 채 팔꿈치를 살짝 굽혀요."}, {"title": "올리기", "text": "팔꿈치가 먼저 올라가게 하며 덤벨을 어깨 높이까지 들어 올려요. 상체를 기울이거나 어깨를 으쓱하지 마세요."}, {"title": "내리기", "text": "2~3초에 걸쳐 천천히 내리고, 아래에서도 긴장을 유지해요."}]}'::jsonb,
   'dumbbell', '{"side_delts": 0.9, "traps": 0.1}'::jsonb, 60, false, '[["dumbbell"], ["bench"]]'::jsonb, 0.17),
  ('seated-dumbbell-rear-delt-fly', '{"en": "Seated Dumbbell Rear Delt Fly", "de": "Reverse Flys mit Kurzhanteln im Sitzen", "pt-PT": "Aberturas invertidas com halteres sentado", "pt-BR": "Crucifixo invertido com halteres sentado", "ko": "시티드 덤벨 리어 델트 플라이"}'::jsonb,
   '{"en": [{"title": "Set up", "text": "Sit on the end of a bench with your feet flat and hinge forward until your chest is close to your thighs, back flat. Let the dumbbells hang beside your calves."}, {"title": "Raise", "text": "With slightly bent elbows, raise the weights out to the sides until your arms line up with your shoulders. Don''t swing."}, {"title": "Lower", "text": "Lower the dumbbells slowly back down without rounding your back or sitting up."}], "de": [{"title": "Position", "text": "Setz dich ans Ende einer Bank, die Füße flach am Boden, und beug dich mit geradem Rücken vor, bis die Brust fast auf den Oberschenkeln liegt. Die Kurzhanteln hängen neben den Waden."}, {"title": "Heben", "text": "Heb die Gewichte mit leicht gebeugten Ellbogen seitlich an, bis die Arme auf Schulterhöhe sind. Nicht schwingen."}, {"title": "Absenken", "text": "Senk die Hanteln langsam wieder ab, ohne den Rücken rund zu machen oder dich aufzurichten."}], "pt-PT": [{"title": "Posição", "text": "Senta-te na ponta de um banco, com os pés bem assentes, e inclina o tronco até o peito ficar perto das coxas, costas direitas. Deixa os halteres pendurados ao lado das pernas."}, {"title": "Elevar", "text": "Com os cotovelos ligeiramente fletidos, eleva os pesos para os lados até os braços ficarem alinhados com os ombros. Sem balançar."}, {"title": "Descida", "text": "Desce os halteres devagar, sem arredondar as costas nem endireitar o tronco."}], "pt-BR": [{"title": "Posição", "text": "Sente na ponta de um banco, pés apoiados no chão, e incline o tronco até o peito ficar perto das coxas, costas retas. Deixe os halteres pendurados ao lado das pernas."}, {"title": "Elevar", "text": "Com os cotovelos levemente flexionados, eleve os pesos para os lados até os braços ficarem alinhados com os ombros. Sem balançar."}, {"title": "Descida", "text": "Desça os halteres devagar, sem arredondar as costas nem levantar o tronco."}], "ko": [{"title": "준비", "text": "벤치 끝에 앉아 발을 바닥에 붙이고, 등을 곧게 편 채 가슴이 허벅지에 가까워질 때까지 상체를 숙여요. 덤벨은 종아리 옆으로 늘어뜨려요."}, {"title": "올리기", "text": "팔꿈치를 살짝 굽힌 채 팔이 어깨와 일직선이 될 때까지 덤벨을 옆으로 들어 올려요. 반동을 쓰지 마세요."}, {"title": "내리기", "text": "등을 굽히거나 상체를 일으키지 않고 덤벨을 천천히 내려요."}]}'::jsonb,
   'dumbbell', '{"rear_delts": 0.7, "upper_back": 0.3}'::jsonb, 60, false, '[["dumbbell"], ["bench"]]'::jsonb, 0.21),
  ('incline-dumbbell-hammer-curl', '{"en": "Incline Dumbbell Hammer Curl", "de": "Schrägbank-Hammercurls mit Kurzhanteln", "pt-PT": "Curl martelo inclinado com halteres", "pt-BR": "Rosca martelo inclinada com halteres", "ko": "인클라인 덤벨 해머 컬"}'::jsonb,
   '{"en": [{"title": "Set up", "text": "Sit back on a bench set to about 45–60°. Let your arms hang straight down with your palms facing your body."}, {"title": "Curl", "text": "Curl the dumbbells up with your thumbs on top, without letting your elbows drift forward. Keep your head and back on the bench."}, {"title": "Lower", "text": "Lower slowly, keeping the neutral grip, until your arms hang straight down again."}], "de": [{"title": "Aufbauen", "text": "Setz dich auf eine Schrägbank mit etwa 45–60° und lehn dich an. Die Arme hängen gestreckt nach unten, Handflächen zum Körper."}, {"title": "Beugen", "text": "Beug die Arme und heb die Hanteln mit den Daumen nach oben, ohne die Ellbogen nach vorn zu schieben. Kopf und Rücken bleiben an der Bank."}, {"title": "Absenken", "text": "Senk die Hanteln im Hammergriff langsam ab, bis die Arme wieder gestreckt nach unten hängen."}], "pt-PT": [{"title": "Preparação", "text": "Senta-te num banco inclinado a 45–60° e encosta as costas. Deixa os braços pendurados, com as palmas viradas para dentro."}, {"title": "Fletir", "text": "Flete os cotovelos e sobe os halteres com os polegares para cima, sem levar os cotovelos para a frente. Mantém a cabeça e as costas no banco."}, {"title": "Descida", "text": "Desce devagar, sem rodar os pulsos, até os braços voltarem a ficar esticados."}], "pt-BR": [{"title": "Preparação", "text": "Sente em um banco inclinado a 45–60° e apoie as costas. Deixe os braços pendurados, com as palmas voltadas para dentro."}, {"title": "Flexionar", "text": "Flexione os cotovelos e suba os halteres com os polegares para cima, sem levar os cotovelos para a frente. Mantenha a cabeça e as costas no banco."}, {"title": "Descida", "text": "Desça devagar, sem girar os punhos, até os braços ficarem estendidos de novo."}], "ko": [{"title": "준비", "text": "약 45–60°로 맞춘 벤치에 등을 기대고 앉아요. 손바닥이 몸 쪽을 향하게 하고 팔을 아래로 곧게 늘어뜨려요."}, {"title": "말아 올리기", "text": "엄지가 위를 향한 채 팔꿈치가 앞으로 나가지 않게 덤벨을 말아 올려요. 머리와 등은 벤치에 붙여요."}, {"title": "내리기", "text": "뉴트럴 그립을 유지하며 팔이 다시 아래로 곧게 늘어질 때까지 천천히 내려요."}]}'::jsonb,
   'dumbbell', '{"biceps": 0.65, "forearms": 0.35}'::jsonb, 60, false, '[["dumbbell"], ["bench"]]'::jsonb, 0.24),
  ('seated-dumbbell-shoulder-press', '{"en": "Seated Dumbbell Shoulder Press", "de": "Kurzhantel-Schulterdrücken im Sitzen", "pt-PT": "Desenvolvimento com halteres sentado", "pt-BR": "Desenvolvimento com halteres sentado", "ko": "시티드 덤벨 숄더 프레스"}'::jsonb,
   '{"en": [{"title": "Set up", "text": "Sit on a bench with the backrest nearly upright, back on the pad and feet flat. Hold the weights at shoulder height, wrists stacked over your elbows."}, {"title": "Press", "text": "Press straight up until your arms are locked out overhead. Keep your hips and back on the bench."}, {"title": "Lower", "text": "Bring the weights back to shoulder height under control without arching your lower back."}], "de": [{"title": "Aufbauen", "text": "Setz dich auf eine fast senkrecht eingestellte Bank, den Rücken am Polster, die Füße flach am Boden. Halte die Gewichte auf Schulterhöhe, Handgelenke über den Ellbogen."}, {"title": "Drücken", "text": "Drück gerade nach oben, bis die Arme über dem Kopf gestreckt sind. Hüfte und Rücken bleiben an der Bank."}, {"title": "Absenken", "text": "Führ die Gewichte kontrolliert zurück auf Schulterhöhe, ohne ins Hohlkreuz zu gehen."}], "pt-PT": [{"title": "Preparação", "text": "Senta-te num banco com o encosto quase na vertical, costas encostadas e pés bem assentes. Segura os pesos à altura dos ombros, pulsos alinhados sobre os cotovelos."}, {"title": "Empurrar", "text": "Empurra a direito para cima até os braços ficarem esticados acima da cabeça. Mantém a anca e as costas no banco."}, {"title": "Descida", "text": "Traz os pesos de volta à altura dos ombros de forma controlada, sem arquear a lombar."}], "pt-BR": [{"title": "Preparação", "text": "Sente em um banco com o encosto quase na vertical, costas apoiadas e pés no chão. Segure os pesos na altura dos ombros, punhos alinhados sobre os cotovelos."}, {"title": "Empurrar", "text": "Empurre reto para cima até os braços ficarem estendidos acima da cabeça. Mantenha o quadril e as costas no banco."}, {"title": "Descida", "text": "Traga os pesos de volta à altura dos ombros com controle, sem arquear a lombar."}], "ko": [{"title": "준비", "text": "등받이를 거의 세운 벤치에 등을 기대고 앉아 발을 바닥에 붙여요. 덤벨을 어깨 높이로 들고 손목이 팔꿈치 바로 위에 오게 해요."}, {"title": "밀기", "text": "팔이 머리 위로 완전히 펴질 때까지 곧게 밀어 올려요. 엉덩이와 등은 벤치에 붙여요."}, {"title": "내리기", "text": "허리를 젖히지 않고 덤벨을 어깨 높이까지 컨트롤하며 내려요."}]}'::jsonb,
   'dumbbell', '{"front_delts": 0.55, "triceps": 0.25, "side_delts": 0.2}'::jsonb, 120, false, '[["dumbbell"], ["bench"]]'::jsonb, 0.4),
  ('assisted-dip-machine', '{"en": "Assisted Dip Machine", "de": "Dips an der Maschine (unterstützt)", "pt-PT": "Fundos assistidos na máquina", "pt-BR": "Mergulho assistido na máquina", "ko": "어시스티드 딥스 머신"}'::jsonb,
   '{"en": [{"title": "Set up", "text": "Select the counterweight: more weight means more help. Kneel on the pad or stand on the platform and grip the dip handles with straight arms."}, {"title": "Lower", "text": "Bend your elbows and lower until your upper arms are about parallel to the floor, chest slightly forward."}, {"title": "Press", "text": "Press back up to straight arms. Reduce the counterweight over time as you get stronger."}], "de": [{"title": "Aufbauen", "text": "Wähl das Gegengewicht: Je mehr Gewicht, desto mehr Unterstützung. Knie dich aufs Polster oder stell dich auf die Plattform und greif die Dip-Griffe mit gestreckten Armen."}, {"title": "Absenken", "text": "Beug die Ellbogen und senk dich ab, bis die Oberarme etwa parallel zum Boden sind, die Brust leicht nach vorn."}, {"title": "Drücken", "text": "Drück dich zurück bis zu gestreckten Armen. Reduziere das Gegengewicht nach und nach, wenn du stärker wirst."}], "pt-PT": [{"title": "Preparação", "text": "Escolhe o contrapeso: quanto mais peso, mais ajuda. Ajoelha-te na almofada ou põe-te de pé na plataforma e agarra as pegas de fundos com os braços esticados."}, {"title": "Descida", "text": "Flete os cotovelos e desce até os braços ficarem mais ou menos paralelos ao chão, com o peito ligeiramente para a frente."}, {"title": "Empurrar", "text": "Empurra de volta até os braços ficarem esticados. Reduz o contrapeso à medida que ficas mais forte."}], "pt-BR": [{"title": "Preparação", "text": "Escolha o contrapeso: quanto mais peso, mais ajuda. Ajoelhe no apoio ou fique em pé na plataforma e segure os pegadores de mergulho com os braços estendidos."}, {"title": "Descida", "text": "Flexione os cotovelos e desça até os braços ficarem mais ou menos paralelos ao chão, com o peito levemente à frente."}, {"title": "Empurrar", "text": "Empurre de volta até os braços ficarem estendidos. Diminua o contrapeso conforme ficar mais forte."}], "ko": [{"title": "준비", "text": "보조 무게를 선택해요. 무게가 무거울수록 더 많이 도와줘요. 패드에 무릎을 대거나 발판에 서서 팔을 편 채 딥스 손잡이를 잡아요."}, {"title": "내리기", "text": "팔꿈치를 굽혀 상완이 바닥과 거의 평행이 될 때까지 내려가요. 가슴은 살짝 앞으로 기울여요."}, {"title": "밀기", "text": "팔이 펴질 때까지 다시 밀어 올려요. 근력이 늘면 보조 무게를 점점 줄여요."}]}'::jsonb,
   'machine', '{"chest": 0.45, "triceps": 0.4, "front_delts": 0.15}'::jsonb, 90, true, '[["machine"]]'::jsonb, 1.4),
  ('seated-leg-press', '{"en": "Seated Leg Press", "de": "Beinpresse im Sitzen", "pt-PT": "Prensa de pernas sentado", "pt-BR": "Leg press sentado", "ko": "시티드 레그 프레스"}'::jsonb,
   '{"en": [{"title": "Feet", "text": "Sit with your back against the pad and place your feet shoulder-width apart in the middle of the footplate. Hold the side handles."}, {"title": "Press", "text": "Push through your whole foot until your legs are almost straight, without locking your knees."}, {"title": "Lower", "text": "Bend your knees slowly back to about 90°."}], "de": [{"title": "Füße", "text": "Setz dich mit dem Rücken ans Polster und stell die Füße schulterbreit in die Mitte der Plattform. Halte dich an den seitlichen Griffen fest."}, {"title": "Drücken", "text": "Drück über den ganzen Fuß, bis die Beine fast gestreckt sind, ohne die Knie durchzustrecken."}, {"title": "Absenken", "text": "Beug die Knie langsam wieder bis etwa 90°."}], "pt-PT": [{"title": "Pés", "text": "Senta-te com as costas encostadas e coloca os pés à largura dos ombros no meio da plataforma. Segura as pegas laterais."}, {"title": "Empurrar", "text": "Empurra com o pé todo até as pernas ficarem quase esticadas, sem bloquear os joelhos."}, {"title": "Descida", "text": "Flete os joelhos devagar até voltares a cerca de 90°."}], "pt-BR": [{"title": "Pés", "text": "Sente com as costas apoiadas e coloque os pés na largura dos ombros no meio da plataforma. Segure os pegadores laterais."}, {"title": "Empurrar", "text": "Empurre com o pé inteiro até as pernas ficarem quase estendidas, sem travar os joelhos."}, {"title": "Descida", "text": "Flexione os joelhos devagar até voltar a cerca de 90°."}], "ko": [{"title": "발 위치", "text": "등을 패드에 붙이고 앉아 발을 어깨너비로 벌려 발판 가운데에 두고, 옆 손잡이를 잡아요."}, {"title": "밀기", "text": "무릎을 잠그지 말고 다리가 거의 펴질 때까지 발바닥 전체로 밀어요."}, {"title": "내리기", "text": "무릎을 약 90°까지 천천히 다시 굽혀요."}]}'::jsonb,
   'machine', '{"quads": 0.6, "glutes": 0.3, "adductors": 0.1}'::jsonb, 120, false, '[["machine"]]'::jsonb, 2.3);

