  ('front-raise', '{"en": "Dumbbell Front Raise", "de": "Frontheben mit Kurzhanteln", "pt-PT": "Elevação frontal com halteres", "pt-BR": "Elevação frontal com halteres", "ko": "덤벨 프론트 레이즈"}'::jsonb),
