  ('seated-cable-row', '{"en": "Seated Cable Row", "de": "Kabelrudern im Sitzen", "pt-PT": "Remada sentada no cabo", "pt-BR": "Remada baixa no cabo", "ko": "시티드 케이블 로우"}'::jsonb)
